#ifndef WEB_PAGE_H
#define WEB_PAGE_H
static const char web_page[] =
"<!doctype html><html lang=\"ru\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>TTGK Audio Bridge</title><style>\n"
":root{color-scheme:dark;--bg:#111316;--panel:#1b1f24;--line:#343b44;--txt:#e8ebef;--muted:#a1aab5;--accent:#92c6ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font:14px system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:16px}header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}h1{font-size:21px;margin:0}h2{font-size:15px;margin:0 0 12px}small,.muted{color:var(--muted)}section{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:14px;margin-bottom:12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}.grid section{margin:0}button,input{font:inherit;color:inherit;background:#262c34;border:1px solid #48525d;border-radius:5px;padding:9px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}input[type=range]{width:100%;padding:0;accent-color:var(--accent)}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0}.val{font-size:28px;font-weight:650;font-variant-numeric:tabular-nums}.kv{display:grid;grid-template-columns:1fr auto;gap:6px;margin:8px 0;font-variant-numeric:tabular-nums}.keys{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.keys span{border:1px solid var(--line);border-radius:5px;padding:8px;text-align:center}.keys .pressed{background:#a9d2ff;color:#101419;border-color:#a9d2ff}pre{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace,monospace;margin:0;background:#111316;padding:10px;border-radius:5px}#msg{min-height:20px;color:var(--accent)}.danger{border-color:#b36b6b}#auth{width:min(100%,290px)}[hidden]{display:none!important}\n"
"</style><main><header><div><h1>TTGK Audio Bridge</h1><small>PS5 · CX31993 · диагностика</small></div><span id=\"conn\" class=\"muted\">Не подключено</span></header>\n"
"<section id=\"login\"><h2>Ключ доступа</h2><p class=\"muted\">16 символов из уведомления PS5 или файла /data/solobridge/web_key. Только доверенная локальная сеть, HTTP без шифрования.</p><div class=\"row\"><input id=\"auth\" type=\"password\" maxlength=\"16\" autocomplete=\"off\" placeholder=\"Ключ доступа\"><button id=\"enter\">Войти</button></div></section>\n"
"<div id=\"msg\" role=\"status\"></div><div id=\"panel\" hidden>\n"
"<div class=\"grid\"><section><h2>Аппаратная громкость</h2><div class=\"val\" id=\"level\">—</div><div class=\"muted\" id=\"confirmed\">—</div><input id=\"vol\" type=\"range\" min=\"0\" max=\"136\" value=\"68\" step=\"1\"><div class=\"row\"><button id=\"minus\">−2 дБ</button><button id=\"plus\">+2 дБ</button><button id=\"mute\">Mute / Unmute</button></div><div class=\"kv\"><span>Предел</span><span id=\"limit\">—</span><span>Автоматический Mute</span><span id=\"gate\">—</span></div></section>\n"
"<section><h2>Аудиодвижок</h2><div id=\"audio\" class=\"kv\"></div></section>\n"
"<section><h2>DualSense</h2><div id=\"pad\" class=\"kv\"></div><div id=\"keys\" class=\"keys\"></div><div class=\"row\"><button id=\"trace\">Лог кнопок (60 с)</button><button id=\"untrace\">Стоп записи</button></div><small>Для теста удерживай L1 + R3 0,5 с, затем стрелку. Последнее нажатие сохраняется даже после отпускания.</small></section></div>\n"
"<section style=\"margin-top:12px\"><div class=\"row\"><h2 style=\"margin:0;flex:1\">Логи</h2><label><input id=\"auto\" type=\"checkbox\" checked> авто</label><button id=\"refresh\">Обновить</button><button id=\"copy\">Копировать</button><button id=\"download\">Скачать лог</button><button id=\"previous\">Предыдущий</button></div><pre id=\"logs\">—</pre></section>\n"
"<section><h2>Сервис</h2><div class=\"row\"><button id=\"off\">Выключить веб до перезапуска</button><button id=\"disable\">Выключить веб постоянно</button><button id=\"stop\" class=\"danger\">Остановить пейлоад</button></div><small>Отключение веб не останавливает звук. Для постоянного отключения удалить disable_web перед следующим запуском.</small></section></div></main><script>\n"
"'use strict';const $=id=>document.getElementById(id);let key='',state=null,editing=false,dead=false,busy=false,logBusy=false,lastLog=0,traceUntil=0;const msg=s=>$('msg').textContent=s;\n"
"const bits=[['L3',2],['R3',4],['↑',16],['→',32],['↓',64],['←',128],['L2',256],['R2',512],['L1',1024],['R1',2048],['△',4096],['○',8192],['×',16384],['□',32768],['Options',8],['Touchpad',1048576],['PS',65536]];\n"
"const stages=['Ожидание захвата','Отключено','Ошибка Mbus','Ошибка модулей','Ошибка NID','Ошибка scePadInit','Ожидание пользователя','Нет handle','Handle получен','Ошибка scePadReadState','Нет подключения','Ввод перехвачен системой','Чтение работает'];\n"
"function hex(v){return '0x'+(v>>>0).toString(16).padStart(8,'0')}function db(v){return v<0?'—':((v&255)/2-74).toFixed(1)+' дБ'}function label(v){return v<0?'—':db(v)+(v&256?' · Mute':'')}\n"
"function kv(id,arr){let el=$(id);el.replaceChildren();for(const [k,v] of arr){let a=document.createElement('span'),b=document.createElement('span');a.textContent=k;b.textContent=v;el.append(a,b)}}\n"
"function names(v){return bits.filter(x=>v&x[1]).map(x=>x[0]).join(' + ')||'—'}\n"
"async function api(path,method='GET'){let r=await fetch(path,{method,headers:{'X-TTGK-Key':key},cache:'no-store',signal:AbortSignal.timeout?AbortSignal.timeout(3500):undefined});if(!r.ok)throw Error(r.status+' '+await r.text());return r}\n"
"function render(s){state=s;$('conn').textContent='Подключено';$('level').textContent=label(s.desired);$('confirmed').textContent='ЦАП: '+(s.hw<0?'нет подтверждения':label(s.hw)+(s.hw&512?' · удерживается Mute':''));$('limit').textContent=db(s.limit);$('gate').textContent=s.gate?'Нет':'Да';if(!editing){$('vol').max=s.limit;$('vol').value=s.desired&255}for(const id of ['vol','minus','plus','mute'])$(id).disabled=!s.online;kv('audio',[['ЦАП',s.usb?'Подключён':'Нет'],['Захват',s.capture?'Активен':'Нет'],['Воспроизведение',s.playing?'Да':'Нет'],['Буфер',Math.round(s.ring/48)+' мс'],['USB очередь (оценка)',(s.queue/8).toFixed(1)+' мс'],['Коррекция',s.phase_ppm+' ppm'],['Underrun',s.underruns],['USB late / blocked',s.late+' / '+s.blocked],['Переподключения',s.reconnects],['Потеря фреймов',s.source_drop]]);let p=s.pad;kv('pad',[['Состояние',stages[p.stage]||p.stage],['Код API',hex(p.error)],['Handle',p.handle],['User',p.user],['Подключён',p.connected?'Да':'Нет'],['Маска',hex(p.buttons)],['Последнее нажатие',names(p.last_pressed)+' '+hex(p.last_pressed)],['Чтения / изменения',p.reads+' / '+p.changes],['Возраст чтения',p.reads?p.age_ms+' мс':'—'],['Комбинация',['Ожидание','Удержание','Активна','Ждёт отпускания'][p.phase]||'—']]);for(const el of $('keys').children)el.classList.toggle('pressed',!!(p.buttons&Number(el.dataset.bit)))}\n"
"for(const [name,bit] of bits){let s=document.createElement('span');s.textContent=name;s.dataset.bit=bit;$('keys').append(s)}\n"
"async function refresh(){if(logBusy||dead)return;logBusy=true;try{let t=await(await api('/api/log')).text();let el=$('logs'),bottom=el.scrollHeight-el.scrollTop-el.clientHeight<50;el.textContent=t;if(bottom)el.scrollTop=el.scrollHeight}catch(e){msg(e.message)}finally{logBusy=false}}\n"
"async function tick(){if(dead||!key)return;if(!busy){busy=true;try{render(await(await api('/api/status')).json());if($('auto').checked&&Date.now()-lastLog>2000){lastLog=Date.now();refresh()}}catch(e){$('conn').textContent='Нет связи';msg(e.message)}finally{busy=false}}setTimeout(tick,Date.now()<traceUntil?200:750)}\n"
"$('enter').onclick=async()=>{if(key)return;key=$('auth').value.trim().toLowerCase();try{if(!/^[a-f0-9]{16}$/.test(key))throw Error('Нужны 16 hex-символов');render(await(await api('/api/status')).json());$('login').hidden=true;$('panel').hidden=false;$('auth').value='';msg('');refresh();tick()}catch(e){key='';msg(e.message)}};\n"
"async function command(path){try{msg(await(await api(path,'POST')).text());return true}catch(e){msg(e.message);return false}}\n"
"function volume(v){if(state)command('/api/volume/'+(Math.max(0,Math.min(state.limit,v))|(state.desired&256)))}\n"
"$('vol').oninput=()=>{editing=true;$('level').textContent=db(Number($('vol').value))};$('vol').onchange=()=>{volume(Number($('vol').value));editing=false};$('minus').onclick=()=>state&&volume((state.desired&255)-4);$('plus').onclick=()=>state&&volume((state.desired&255)+4);$('mute').onclick=()=>state&&command('/api/volume/'+(state.desired^256));\n"
"$('trace').onclick=async()=>{if(await command('/api/trace/on'))traceUntil=Date.now()+60000};$('untrace').onclick=()=>{traceUntil=0;command('/api/trace/off')};$('refresh').onclick=refresh;\n"
"$('copy').onclick=async()=>{try{if(navigator.clipboard)await navigator.clipboard.writeText($('logs').textContent);else{let t=document.createElement('textarea');t.value=$('logs').textContent;document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error('Копирование запрещено браузером');t.remove()}msg('Лог скопирован')}catch(e){msg(e.message)}};\n"
"async function download(path,name){try{let blob=await(await api(path)).blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){msg(e.message)}}$('download').onclick=()=>download('/api/log/full','solobridge-log.txt');$('previous').onclick=()=>download('/api/log/previous','solobridge-log-previous.txt');\n"
"async function shutdown(path,prompt){if(confirm(prompt)&&await command(path)){dead=true;$('conn').textContent='Отключено';$('panel').querySelectorAll('button,input').forEach(e=>e.disabled=true)}}$('off').onclick=()=>shutdown('/api/web/off','Выключить только веб-панель до следующего запуска?');$('disable').onclick=()=>shutdown('/api/web/disable','Выключить веб-панель постоянно? Для включения понадобится удалить disable_web.');$('stop').onclick=()=>shutdown('/api/stop','Остановить звук и весь пейлоад?');\n"
"</script></html>\n";
#endif
